import re

def parse(lines):
    props = {}
    pl = []
    depth = []
    dl = []
    stats = []
    sl = []
    hist = []
    hl = []
    skip = []
    section = None
    cur = None
    hre = re.compile(r'^\s*(\d+):\s+\((?P<c>[^)]*)\)\s+(?P<hex>#[0-9A-Fa-f]+)(?:\s+(?P<name>.*\S))?\s*$')
    kre = re.compile(r'^(\s*)(.+?):(?:\s+(.*?)|)\s*$')
    vre = re.compile(r'^(\S+)(?:\s+\((\S+)\))?$')
    for i, l in enumerate(lines):
        if not l.strip():
            continue
        ind = len(l) - len(l.lstrip())
        if section == 'Histogram':
            m = hre.match(l)
            if m:
                hist.append({'Count': int(m.group(1)), 'Color': m.group('c'), 'Hex': m.group('hex'), 'Name': m.group('name') or ''})
                hl.append(i)
                continue
        m = kre.match(l)
        if not m:
            continue
        key = m.group(2).strip()
        val = m.group(3) or ''
        if ind == 0:
            section = None
            cur = None
            if val:
                props[key] = val
                pl.append(i)
            else:
                skip.append(i)
            continue
        if ind <= 2:
            cur = None
            if val:
                section = None
                props[key] = val
                pl.append(i)
            else:
                section = key
                skip.append(i)
            continue
        if section == 'Channel depth':
            depth.append({'Channel': key, 'Depth': val})
            dl.append(i)
        elif section in ('Channel statistics', 'Image statistics'):
            if ind <= 4 and not val:
                cur = {'Section': section, 'Channel': key}
                stats.append(cur)
                sl.append(i)
            elif ind <= 4:
                props[key] = val
                pl.append(i)
            elif cur is not None:
                v = vre.match(val)
                if v:
                    cur[key] = v.group(1)
                    if v.group(2) is not None:
                        cur[key + ' (normalized)'] = v.group(2)
                else:
                    cur[key] = val
                sl.append(i)
        else:
            if val:
                props[(section + ' ' if section else '') + key] = val
                pl.append(i)
            else:
                skip.append(i)
    blocks = []
    if props:
        blocks.append({'name': 'image', 'kind': 'kv', 'lines': pl, 'records': [props]})
    if depth:
        blocks.append({'name': 'channel_depth', 'kind': 'table', 'lines': dl, 'records': depth})
    if stats:
        blocks.append({'name': 'statistics', 'kind': 'table', 'lines': sl, 'records': stats})
    if hist:
        blocks.append({'name': 'histogram', 'kind': 'table', 'lines': hl, 'records': hist})
    return {'blocks': blocks, 'skip': skip}
